sparql_tries.sparql:
SELECT DISTINCT ?year WHERE {
  ?c rc:campaignNumber "26V430000" ;
     rc:affects ?v .
  ?v rc:ofModel ?m ;
     rc:modelYear ?year .
  ?m rc:name "TELLURIDE" ;
     rc:ofMake ?mk .
  ?mk rc:name "KIA" .
}
ORDER BY ?year

SELECT DISTINCT ?componentName WHERE {
  ?c rc:campaignNumber "10V388000" ;
     rc:affectsComponent ?comp .
  ?comp rc:name ?componentName .
}
ORDER BY ?componentName

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:doNotDrive true ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(UCASE(STR(?makeName)) IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?initiatedBy WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:initiatedBy ?initiatedBy .
  FILTER(CONTAINS(UCASE(STR(?initiatedBy)), "OVSC"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:reportReceivedDate ?date ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name "PALISADE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(?date >= "2024-01-01"^^xsd:date && ?date <= "2024-12-31"^^xsd:date)
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?makeName ?modelName WHERE {
  ?target a rc:Component ;
          rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?comp skos:broader* ?target .
  ?rc rc:affectsComponent ?comp ;
      rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
ORDER BY ?makeName ?modelName

SELECT ?componentName (COUNT(DISTINCT ?c) AS ?campaignCount) WHERE {
  ?comp skos:broader ?parent ;
        rc:name ?componentName .
  ?c rc:affectsComponent ?comp .
  FILTER EXISTS {
    ?c1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake ?mk1 .
    ?mk1 rc:name "HYUNDAI" .
  }
  FILTER EXISTS {
    ?c2 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake ?mk2 .
    ?mk2 rc:name "KIA" .
  }
}
GROUP BY ?componentName
ORDER BY DESC(?campaignCount) ?componentName

SELECT ?campaignNumber (COUNT(DISTINCT ?make) AS ?makeCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?makes)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?make .
  ?make rc:name ?makeName .
}
GROUP BY ?campaignNumber
HAVING (COUNT(DISTINCT ?make) > 1)
ORDER BY DESC(?makeCount) ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:affects ?v .
  ?v rc:ofModel ?m ;
     rc:modelYear ?y .
  ?m rc:name "SANTA FE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(STR(?y) = "2021")
}
ORDER BY ?campaignNumber

SELECT ?modelName ?makeName (COUNT(DISTINCT ?c) AS ?campaignCount)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:name ?modelName .
  OPTIONAL { ?m rc:ofMake ?mk . ?mk rc:name ?makeName . }
}
GROUP BY ?m ?modelName ?makeName
ORDER BY DESC(?campaignCount) ?makeName ?modelName

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(?d >= "2023-01-01"^^xsd:date && ?d <= "2023-12-31"^^xsd:date)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affectsComponent ?comp ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?top ?topName
ORDER BY DESC(?modelCount)

SELECT ?campaignNumber ?affected WHERE {
  ?c a rc:RecallCampaign ;
     rc:parkOutside true ;
     rc:campaignNumber ?campaignNumber ;
     rc:potentiallyAffected ?affected .
}
ORDER BY DESC(?affected)
LIMIT 1

SELECT (COUNT(DISTINCT ?c) AS ?count) WHERE {
  ?c a rc:RecallCampaign ;
     rc:initiatedBy ?by .
  FILTER(CONTAINS(UCASE(STR(?by)), "ODI"))
}

SELECT ?topName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?c a rc:RecallCampaign ;
     rc:affects ?v ;
     rc:affectsComponent ?comp .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) = "GENESIS")
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?anyParent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns) ?topName

SELECT (COUNT(DISTINCT ?year) AS ?count) WHERE {
  ?c a rc:RecallCampaign ; rc:affects ?v .
  ?v rc:ofModel ?m ; rc:modelYear ?year .
  ?m rc:name "SONATA" ; rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
}

SELECT ?year (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?n) ?year

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?r a rc:RecallCampaign ; rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:reportReceivedDate ?date }
  {
    ?r rc:defectSummary ?t
  } UNION {
    ?r rc:consequenceSummary ?t
  } UNION {
    ?r rc:rootCause ?t
  } UNION {
    ?r rc:affectsComponent ?c . ?c rc:name ?t
  }
  FILTER(REGEX(STR(?t), "hydrogen", "i"))
}
ORDER BY DESC(?date) ?campaignNumber

SELECT DISTINCT ?campaignNumber WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:defectSummary ?d }
  OPTIONAL { ?r rc:correctiveSummary ?c }
  OPTIONAL { ?r rc:affectsComponent/rc:name ?cn }
  FILTER(
    REGEX(COALESCE(?d, ""), "ICCU|integrated charging control unit", "i") ||
    REGEX(COALESCE(?c, ""), "ICCU|integrated charging control unit", "i") ||
    REGEX(COALESCE(?cn, ""), "ICCU|integrated charging control unit", "i")
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?date WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?r rc:reportReceivedDate ?date }
  OPTIONAL { ?r rc:defectSummary ?d }
  OPTIONAL { ?r rc:rootCause ?rc }
  OPTIONAL { ?r rc:consequenceSummary ?cs }
  BIND(LCASE(CONCAT(COALESCE(?d,""), " ", COALESCE(?rc,""), " ", COALESCE(?cs,""))) AS ?t)
  FILTER(REGEX(?t, "water|moisture|fluid intrusion|liquid"))
  FILTER(REGEX(?t, "trailer|tow"))
  FILTER(REGEX(?t, "module"))
}
ORDER BY ?date ?campaignNumber

SELECT DISTINCT ?campaignNumber ?defectSummary WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:defectSummary ?defectSummary .
  OPTIONAL { ?r rc:rootCause ?rootCause }
  BIND(LCASE(CONCAT(STR(?defectSummary), " ", COALESCE(STR(?rootCause), ""))) AS ?txt)
  FILTER(CONTAINS(?txt, "connecting rod") && CONTAINS(?txt, "bearing"))
  FILTER(REGEX(?txt, "wear|worn", "i"))
}
ORDER BY ?campaignNumber
